{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'roger-bucket-2' does not have versioning enabled, which can lead to data loss if objects are accidentally deleted or overwritten."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'roger-bucket-2' does not have access logging enabled, making it difficult to track and monitor access to the bucket."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'roger-bucket-2' does not have a Public Access block configured, which can expose the bucket to unauthorized public access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"bucket_2\" {\n  bucket = \"roger-bucket-2\"\n  acl    = var.bucket_acl\n  versioning {\n    enabled = true\n  }\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        kms_master_key_id = aws_kms_key.my_key.arn\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n  logging {\n    target_bucket = \"${aws_s3_bucket.bucket_2.id}-logs\"\n    target_prefix = \"/logs/\"\n  }\n}\nresource \"aws_s3_bucket_public_access_block\" \"bucket_2_public_access_block\" {\n  bucket = aws_s3_bucket.bucket_2.id\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled versioning for the S3 bucket, added access logging, and configured a Public Access block to prevent unauthorized public access."
}
